 logo_addr0<={ly[6:0],lx[6:2]};
 panel1<=panel0;logo1<=logo0;text1<=text0;group1<=group0;
 end end
 genvar k;
 generate for(k=0;k<4;k=k+1)begin:lane
 wire ink=text1&&font_row[31-({group1,2'b00}+k)];
